/* ==================================================   Sky Empire — application mobile (PWA)
   Installation sur l'écran d'accueil, plein écran, hors ligne,
   transfert de la partie entre Safari et l'application.
   ========================================================= */
'use strict';
const isStandalone=()=>window.matchMedia('(display-mode: standalone)').matches||window.matchMedia('(display-mode: fullscreen)').matches||window.navigator.standalone===true;
const isIOS=()=>/iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
let _installEvt=null;
window.addEventListener('beforeinstallprompt',e=>{ e.preventDefault(); _installEvt=e; });
window.addEventListener('appinstalled',()=>{ try{ localStorage.setItem('se-installed','1'); }catch(e){} toast('📲 Sky Empire est installé sur votre écran d’accueil !','ok'); });
if('serviceWorker' in navigator && location.protocol!=='file:'){
  window.addEventListener('load',()=>{ navigator.serviceWorker.register('sw.js').catch(()=>{}); });
}
if(isStandalone()) document.documentElement.classList.add('pwa');

function installHtml(){
  const ios=isIOS();
  const steps=ios? `<ol class="inst">
      <li>Dans <b>Safari</b> ou <b>Chrome</b>, touchez le bouton <b>Partager</b> <span class="ico">⬆️</span> (dans Chrome : en haut à droite, à côté de l’adresse).</li>
      <li>Faites défiler et touchez <b>« Sur l’écran d’accueil »</b> <span class="ico">➕</span>.</li>
      <li>Touchez <b>Ajouter</b>. L’icône <b>Sky Empire</b> ✈️ apparaît sur votre écran d’accueil.</li>
      <li>Ouvrez le jeu <b>depuis cette icône</b> : il s’affiche en plein écran, comme une vraie application, sans la barre de Safari.</li></ol>
      <p class="small mut">Marche avec Safari, et avec Chrome sur iOS 16.4 ou plus récent. Pas depuis l’appli Google ni depuis un lien ouvert dans une autre appli.</p>`
    : _installEvt? `<p>Touchez le bouton ci-dessous, puis <b>Installer</b>.</p><div class="btns"><button class="btn gold" data-act="pwaPrompt">📲 Installer Sky Empire</button></div>`
    : `<ol class="inst"><li>Ouvrez le menu du navigateur <b>⋮</b> (en haut à droite).</li><li>Touchez <b>« Installer l’application »</b> ou <b>« Ajouter à l’écran d’accueil »</b>.</li><li>Ouvrez ensuite le jeu depuis l’icône <b>Sky Empire</b> ✈️.</li></ol>`;
  return `${isStandalone()?`<div class="al ok">✅ Vous utilisez déjà l’application Sky Empire.</div>`:''}
    <p>Installez Sky Empire comme une <b>application</b> : icône sur l’écran d’accueil, plein écran, démarrage rapide, et le jeu marche même avec une connexion faible.</p>
    ${isStandalone()?'':steps}
    <h3>🔁 Garder ma partie</h3>
    <p class="small">${ios?'Sur iPhone, l’application installée, Safari et Chrome ont chacun leur propre mémoire.':'L’application et le navigateur peuvent avoir chacun leur mémoire.'} Pour retrouver votre compagnie dans l’application :</p>
    <ol class="inst"><li>${isStandalone()?'Dans le navigateur où vous jouiez avant (Chrome ou Safari)':'Ici, avant d’installer'} : touchez <b>📋 Copier ma partie</b>.</li><li>Dans l’application : <b>Plus → 📲 Application → 📥 Coller une partie</b>.</li></ol>
    <div class="btns"><button class="btn" data-act="pwaCopy">📋 Copier ma partie</button><button class="btn" data-act="pwaPaste">📥 Coller une partie</button></div>`;
}
function registerPwaActions(){
  MODALS.install=()=>showModal('📲 Application mobile', installHtml());
  Object.assign(ACTIONS,{
    install:()=>openM('install'),
    pwaPrompt:async()=>{ if(!_installEvt) return openM('install'); _installEvt.prompt(); try{ await _installEvt.userChoice; }catch(e){} _installEvt=null; closeModal(); },
    pwaCopy:async()=>{ save(); const data=localStorage.getItem(SAVE_KEY)||JSON.stringify(S);
      try{ await navigator.clipboard.writeText(data); toast(`📋 Partie copiée (${Math.round(data.length/1024)} Ko). Ouvrez l’application et touchez « Coller une partie ».`,'ok'); }
      catch(e){ showModal('📋 Copier ma partie',`<p class="small">Sélectionnez tout le texte ci-dessous et copiez-le :</p><textarea class="savebox" readonly onfocus="this.select()">${esc(data)}</textarea>`); } },
    pwaPaste:async()=>{ let txt='';
      try{ txt=await navigator.clipboard.readText(); }catch(e){}
      if(!txt||txt[0]!=='{'){ showModal('📥 Coller une partie',`<p class="small">Collez ici la partie copiée (appui long → Coller) :</p><textarea class="savebox" id="pasteBox"></textarea><div class="btns"><button class="btn gold" data-act="pwaPasteGo">✅ Charger cette partie</button></div>`); return; }
      pwaLoad(txt); },
    pwaPasteGo:()=>{ const t=(document.getElementById('pasteBox')||{}).value||''; pwaLoad(t.trim()); },
  });
}
function pwaLoad(txt){
  if(typeof applySave==='function') return applySave(txt,'Charger');
  try{ const o=JSON.parse(txt); if(!o||!o.company||!o.fleet||!o.time) throw new Error('ce n’est pas une partie Sky Empire');
    if(!confirm(`Charger la partie « ${o.company.name} » ? La partie actuelle de cet appareil sera remplacée.`)) return;
    localStorage.setItem(SAVE_KEY,txt); location.reload(); }
  catch(e){ toast('⛔ Partie illisible : '+e.message,'bad'); }
}
// Proposition d'installation : une fois, sur téléphone, dans le navigateur
function maybeInstallHint(){
  if(isStandalone()) return; if(!(UI&&UI.mobile)&&!isIOS()) return;
  let n=0; try{ n=+(localStorage.getItem('se-inst-hint')||0); }catch(e){}
  if(n>=3) return; try{ localStorage.setItem('se-inst-hint',String(n+1)); }catch(e){}
  setTimeout(()=>{ const b=document.createElement('div'); b.id='instBar';
    b.innerHTML=`<span>📲 Installez <b>Sky Empire</b> sur votre écran d’accueil : plein écran, comme une vraie appli.</span><button class="btn sm gold" data-act="install">Comment ?</button><button class="x" aria-label="Fermer">×</button>`;
    b.querySelector('.x').onclick=()=>b.remove(); b.querySelector('[data-act]').addEventListener('click',()=>setTimeout(()=>b.remove(),50));
    document.body.appendChild(b); setTimeout(()=>b.remove(),20000); },4000);
}

/* ---------- mises à jour et nouveautés ---------- */
const GAME_VER='20261220';
async function checkUpdate(manual){
  try{
    const r=await fetch('index.html?cb='+Date.now(),{cache:'no-store'}), t=await r.text(), m=t.match(/name="se-ver" content="(\d+)"/), cur=(document.querySelector('meta[name="se-ver"]')||{}).content;
    if(m&&cur&&m[1]!==cur){
      if(sessionStorage.getItem('se-upd')===m[1]){ if(manual) toast('Mise à jour déjà demandée : fermez complètement l’appli puis rouvrez-la.','warn'); return; }
      sessionStorage.setItem('se-upd',m[1]); toast('🔄 Mise à jour du jeu…','ok'); try{ save(); }catch(e){}
      if('serviceWorker' in navigator){ const rg=await navigator.serviceWorker.getRegistrations(); for(const x of rg) await x.unregister(); }
      if(window.caches){ for(const k of await caches.keys()) await caches.delete(k); }
      location.reload(); return;
    }
    if(manual) toast('✅ Le jeu est à jour (version '+cur+')','ok');
  }catch(e){ if(manual) toast('Impossible de vérifier : pas de connexion ?','warn'); }
}
const WHATS_NEW=[
  ['🛫 L’avion tourne tout seul vers la piste','Au roulage, les virages sont arrondis et l’avion s’aligne doucement dans l’axe de la piste (plus de pivot d’un coup), aussi depuis le point d’attente. Rotation à la vraie vitesse de décollage. 🎙️ Annonces du cockpit (V1, Rotate, 50-40-30, Retard…) et de l’équipage, grondement des roues, traînées blanches en croisière, gerbes d’eau sous la pluie.'],
  ['✈️ Décollages et atterrissages plus réalistes','Rotation vers 200 km/h, montée nez haut, approche stabilisée sans plongeon, arrondi avant le toucher puis le nez qui redescend doucement. Et la 3D devient plus nette toute seule quand le téléphone a de la marge (elle s’allège toujours si ça rame).'],
  ['🗺️ Mini-carte bien visible en 3D','La petite carte est maintenant en haut à gauche, sous les boutons (elle était cachée sous le tableau de bord). Elle montre l’avion, sa route, la ville de départ 🛫 et d’arrivée 🛬, et au-dessus : le pays et la ville la plus proche, et les kilomètres restants.'],
  ['🛟 3D qui tient dans la durée','Correction importante : à chaque renouvellement des nuages, leurs images étaient recopiées dans la mémoire graphique sans jamais être libérées. Au bout de 10 minutes environ, l’iPhone était plein et rechargeait le jeu (retour à Kinshasa). Maintenant la mémoire reste stable.'],
  ['☁️ Nuages plus beaux','Nuages redessinés : sommet éclairé par le soleil, base grise, en grappes pour avoir du volume ; voiles fins en altitude ; sous l’orage, cumulonimbus sombres jusqu’à 11 km avec leur enclume.'],
  ['⛈️ Pluie et orage','Pluie visible sur tout l’écran (inclinée selon la vitesse, plus forte sous l’orage), gouttes sur le pare-brise en cockpit. Vrais éclairs en 3D du nuage au sol, flash selon la distance, tonnerre qui arrive après. Le bouton ☁️ « Orage » déclenche tout.'],
  ['🛟 3D qui ne se ferme plus à l’ouverture','Sur téléphone la 3D charge beaucoup moins au démarrage : 12 de vos avions au lieu de 25, seul l’avion suivi est détaillé (les autres en version légère), nuages et trafic d’ambiance arrivent après quelques secondes. Si la 3D a planté la fois d’avant, elle redémarre directement allégée.'],
  ['🛟 3D qui s’allège toute seule','Dans tous les modes (même Minimal), la 3D mesure si le téléphone suit. Sinon elle retire les décors par étapes (trafic d’ambiance, nuages, avions des autres compagnies, aéroport vivant, résolution) au lieu de ramer ou de se fermer. Elle les remet quand ça redevient fluide.'],
  ['☁️ Choisissez vos nuages','Nouveau bouton ☁️ en 3D : météo du jeu, pas de nuages, quelques nuages, nuageux, très nuageux (des nuages aussi à l’altitude de l’avion) ou orage. Le choix est gardé. Les nuages apparaissent maintenant devant l’avion, sur sa route.'],
  ['🔄 Virages en 3D','En 3D les avions tournent vraiment pour s’aligner sur la piste (et à chaque changement de cap), au lieu de sauter d’un coup sur l’axe : trajectoire lissée, inclinaison dans les virages. Pareil pour les avions des autres compagnies.'],
  ['✈️ Trafic des autres compagnies en 3D','Autour de l’avion suivi, d’autres avions aux couleurs des compagnies de la région : en croisière à d’autres niveaux de vol, et près des aéroports en finale alignés sur la piste ou au décollage.'],
  ['☁️ Plus de nuages','Ciel nuageux beaucoup plus souvent (dégagé environ 1 jour sur 7) et nuages plus proches de l’avion.'],
  ['☁️ Nuages en 3D','Des nuages autour de votre avion, aussi sur téléphone : cumulus bas, parfois une couche plus haute, gros nuages sombres sous les orages. Pas toujours : selon la région et le jour, ciel dégagé, quelques nuages ou ciel chargé. En montant, l’avion les traverse puis les voit en dessous.'],
  ['🗺️ Mini-carte de retour en 3D','La petite carte revient à l’écran (même si elle avait été cachée) et suit l’avion : sa position, son cap, sa route en pointillés et sa ville d’arrivée ; zoom selon l’altitude.'],
  ['🇨🇩 FlyCAA et Masambukidi Fly vraiment fortes','Les compagnies de votre pays ne disparaissent plus, ne sont plus rachetées par l’étranger, ne perdent plus leurs lignes face aux étrangères et ne vendent plus leurs avions : elles grandissent chaque semaine. Une compagnie congolaise disparue renaît (une fois).'],
  ['🧠 IA plus maligne','Les compagnies ouvrent la ligne la plus prometteuse depuis leur hub (forte demande, peu de concurrents) quand elles grandissent, ferment leur ligne la plus faible quand elles souffrent ; les bien gérées montent, les mal gérées coulent.'],
  ['🛂 Contrôle des passagers plus détaillé','Refus calculés de la même façon pour toutes les compagnies (plus seulement les vôtres), numéro de vol et ville de départ, motif de chaque refus, bilan du jour par compagnie, motifs de refus, douane (fouilles, saisies, droits), nationalités dans la file.'],
  ['🗼 Tour de contrôle et radar détaillés','Météo de l’aéroport (vent, rafales, visibilité, température, QNH, information ATIS), piste en service face au vent, compteurs (approche, départ, attente, sol), prochains atterrissages, fiches de vol de tous les avions (compagnie, phase, altitude, vitesse, distance, heure d’arrivée) et traînées sur le radar.'],
  ['🇵🇸 Palestine','Nouveau pays : la Palestine, avec l’aéroport international Yasser-Arafat de Gaza (GZA, piste de 3 076 m). Fermé dans la réalité depuis 2001, il est rouvert dans le jeu : ouvrez une ligne, il s’affiche aussi en 3D.'],
  ['🛬 Tous vos aéroports visibles en 3D','Bukavu, Kamina, Manono et 24 autres aéroports n’avaient pas de piste dans la base du jeu : la 3D ne les dessinait pas. Maintenant la vraie piste est téléchargée (OpenStreetMap) ou reconstruite : piste, balisage, terminal et avions s’affichent. « Allonger la piste » se voit aussi en 3D.'],
  ['🛡️ 3D plus légère pour les grosses flottes','Sur téléphone, la 3D n’affiche que vos 25 avions les plus proches (plus l’avion suivi) au lieu de tous vos vols du monde : beaucoup moins de mémoire et de calcul.'],
  ['🇨🇩 Des rivaux congolais plus puissants','Masambukidi Fly grandit plus vite jusqu’à 240 avions, peut ouvrir jusqu’à 3 lignes par semaine et bâtir des bases à l’étranger. Les autres compagnies congolaises progressent aussi plus régulièrement (plafond de 160 avions), étendent leur réseau et Masambukidi peut racheter des compagnies étrangères fragiles. Elles restent non agressives contre votre compagnie.'],
  ['🧹 Fin d’événement : lignes fermées, avions vendus','Les lignes ouvertes vers la ville d’un grand événement sont fermées à la fin, et les avions achetés pour l’événement sont vendus (en vol : à l’atterrissage). Les avions qui volent aussi ailleurs sont gardés. Case « Garder » dans 🏟️. Pour les anciens événements (São Paulo…) : liste à cocher dans 🏟️ pour fermer et vendre.'],
  ['🛡️ 3D plus légère sur téléphone','Pour éviter que la 3D se ferme (mémoire graphique pleine) : sur téléphone, les avions des autres compagnies utilisent un modèle allégé (2× moins lourd), l’aéroport vivant montre 4 avions au lieu de 6. Vos avions gardent le modèle détaillé.'],
  ['🎥 Cockpit et cabine de nouveau fluides','Correction : en vue cockpit / cabine la caméra tremblait depuis la dernière version. L’avion et la caméra utilisent maintenant la même heure à chaque image : l’avion avance tranquillement.'],
  ['🎥 3D : feux collés à l’avion, moins d’arrêts','L’avion, ses feux (rouge, vert, flashs) et la caméra utilisent exactement le même instant à chaque image : les feux ne flottent plus à côté de l’avion. Un petit ralentissement du téléphone ne fige plus l’avion, et en 3D la partie s’enregistre toutes les 2 minutes au lieu de 30 secondes (moins d’à-coups).'],
  ['🎥 3D plus stable','L’avion ne recule plus et ne saute plus : nouvelle horloge d’affichage qui avance en continu et se recale en douceur sur le temps du jeu, même quand le téléphone ralentit (aussi sur la carte 2D).'],
  ['🌍 Le monde bouge en continu','Chaque compagnie évolue à sa propre heure (flotte, argent, image, accidents) au lieu de toutes ensemble le lundi : actualités, sécurité, nouvelles, classement, réseau, flotte et patrimoine changent au fil des heures. Les présidents prennent aussi des décisions en cours de semaine. Tous les onglets d’actualités et le contrôle des passagers se redessinent chaque seconde.'],
  ['🛂 Contrôle des passagers en direct','Nouvel encadré « ● En direct au contrôle » : arrivés depuis minuit (le compteur monte chaque minute), dernière heure, file et temps d’attente, refoulés du jour, et tableau des dernières arrivées (vos vols ⭐ et ceux des autres compagnies).'],
  ['🏆 Classement en direct','Le classement bouge chaque seconde avec le temps du jeu : le patrimoine des compagnies évolue heure par heure, vos passagers/jour = voyageurs réellement débarqués sur les 24 dernières heures, ceux des concurrents suivent les pointes du matin et du soir. Le tableau se redessine tout seul.'],
  ['🗓️ Horaires respectés','Sur une ligne avec plusieurs avions, les départs de la semaine sont répartis régulièrement (ex. 6 h 30, 12 h 15, 18 h 00) et donnés aux avions à tour de rôle. Deux avions de la même ligne ne partent plus l’un derrière l’autre : un écart minimum est toujours gardé, même quand un avion revient en retard.'],
  ['🤝 Adjoint : vous choisissez les lignes','Dites-lui le pays et le budget : il propose jusqu’à 12 lignes. Cochez seulement celles que vous voulez, il n’ouvre que celles-là (audit, avion, décollage et personnel compris). Il n’ouvre plus jamais de ligne tout seul.'],
  ['🤝 L’adjoint fait tout','Il fait lui-même les audits des lignes, les avions décollent tout de suite (on les voit en 2D et en 3D), et il recrute pilotes, PNC, mécaniciens et personnel au sol. Chaque semaine il audite les nouvelles lignes de son hub et complète le personnel.'],
  ['🗺️ Carte : lignes et avions bien visibles','Vos lignes retrouvent leur couleur et leur épaisseur, vos avions leur taille normale, le fond n’est presque plus assombri. On garde seulement les noms de villes qui ne se chevauchent plus et les petites traînées.'],
  ['🏟️ Vols spéciaux réparés','Tous vos avions libres partent tout de suite vers l’événement, avec des escales techniques si l’autonomie ne suffit pas ; l’équipage manquant est recruté automatiquement ; un message dit combien sont partis et pourquoi les autres restent. Les supporters qui arrivent en avance comptent.'],
  ['✨ Carte plus belle','Vue épurée : les noms de villes ne se chevauchent plus, lignes plus fines, petites traînées derrière les avions, avions concurrents plus discrets, fond un peu assombri pour faire ressortir vos avions, moins de boutons à gauche. Bouton « ✨ Vue épurée » dans ⚙️ Options pour revenir à l’ancienne carte.'],
  ['🤝 Adjoints : nouvelles lignes','Votre adjoint laisse de côté les villes où vous avez déjà une ligne depuis ce hub : il ouvre seulement des lignes nouvelles, un avion par ligne. Une case permet aussi de renforcer vos lignes existantes.'],
  ['🤝 Adjoints','Onglet Lignes → « Mes adjoints » : engagez un adjoint pour un hub, dites-lui le pays et le budget. Il trouve les lignes les plus rentables, achète (ou loue) les avions, ouvre les lignes, programme les vols et recrute les pilotes. Mode automatique : il réinvestit chaque semaine.'],
  ['✈️ Avions 3D plus détaillés','Hublots un par un, portes dessinées, vraies vitres de cockpit, nez arrondi, carénage sous le ventre et rails de volets, moteurs avec cône d’entrée et tuyère, ailes plus claires ; A380 avec ses deux rangées de hublots.'],
  ['🛬 Aéroport 3D vivant','Plus d’avions des autres compagnies aux portes, à leurs couleurs, avec citerne, camion-repas, tapis et chariots ; passagers qui descendent du bus et montent l’escalier arrière ; tracteurs à bagages, bus et citernes qui roulent sur une route de service ; avions qui roulent sur la voie de circulation.'],
  ['🏟️ Grands événements mondiaux','Tous les 10 à 15 jours, une ville accueille un grand événement (CAN, Coupe du monde, JO, Hajj, carnaval de Rio, méga-concert de rumba, Festival Amani…). Annoncé 3 jours avant, il dure 6 jours : la demande vers la ville explose et c’est la course contre les autres compagnies pour transporter le plus de voyageurs, classement en direct. Touchez 🏟️ (bouton à droite ou icône sur la carte) puis « ✈️ Lancer des vols spéciaux » : vos avions libres décollent vraiment vers l’événement. Récompenses : trophées (salle des trophées) et ⭐ prestige à dépenser dans la boutique (ambassadeur star, campagne mondiale, partenaire officiel, A380 doré « Léopard d’Or », Concorde de collection).'],
  ['🎥 Suivre l’avion sans la grosse fiche','Quand vous suivez un avion, sa fiche se réduit en une petite barre en bas (vol, altitude, vitesse, arrivée, progression) : vous voyez l’avion bouger sur la carte. ⬆️ Détails rouvre la fiche complète, ▾ la réduit, ✖ la ferme. La fiche complète ne dépasse plus la moitié de l’écran.'],
  ['🧭 Les tracés suivent les vraies routes','Les lignes dessinées sur la carte 2D et en 3D ne sont plus droites : elles montrent la vraie route de l’avion en vol sur la ligne (ou la route du jour), aller en trait plein, retour en pointillés, et changent à chaque vol. Les avions des autres compagnies qui s’écartent de la ligne droite restent visibles.'],
  ['🧭 Routes différentes, sans grand détour','Chaque vol (aller, retour, chaque nouveau départ, chaque compagnie) prend un chemin différent, d’un côté ou de l’autre de la route directe, avec un détour de 4 à 20 % au maximum — plus de grands crochets par une autre région.'],
  ['🧭 Chaque vol a sa propre route','Les avions (les vôtres et ceux de toutes les compagnies) suivent maintenant des points de passage — villes, îles, balises — choisis à chaque vol : l’aller, le retour et le vol suivant ne prennent jamais le même chemin. Le détour reste raisonnable (3 à 10 %, parfois une route plus large par l’océan ou une autre région). La fiche du vol affiche la « 🧭 Route du jour : via … ».'],
  ['😶 Un pays que tout le monde fuit','🧬 Éditeur → 🌍 Pays : nouveau curseur « Activité aérienne » de 0 à 150 %. En baissant, moins de gens veulent y aller ; sous 35 %, plus personne ne veut y aller et les compagnies suspendent leurs vols (leurs avions disparaissent) ; à 0 %, plus aucun vol, les aéroports ferment. Au-dessus de 100 %, le pays attire du monde. Boutons rapides et retour à la normale à tout moment.'],
  ['🌍 Qui vient dans chaque pays, et pourquoi','Dans 🛂 Voyageurs (et depuis la fiche de votre pays) : pour chaque pays, les nationalités qui arrivent, combien par an, leurs motifs (affaires, famille, tourisme, études, travail, soins, religion, humanitaire) et une explication concrète — par exemple les Chinois au Congo pour les mines de cuivre et de cobalt et les chantiers, les Rwandais pour le commerce avec Goma, les Congolais de Belgique pour la famille. Estimations du jeu.'],
  ['🏗️ Les terminaux ne coupent plus les routes','Quand un aéroport a des terminaux 2, 3 ou 4, le jeu regarde les vraies routes autour (OpenStreetMap) et place chaque terminal là où il en coupe le moins ; la 2D, la 3D et les portes suivent. En 3D, une route qui passe encore sous un terminal en fait le tour, et les voitures aussi.'],
  ['🧭 Trajets libres et vols en courbe','Bus et camions : « 🧭 Prolonger le trajet jusqu’à… » ajoute n’importe quelle ville à la fin de la ligne, dans l’ordre que vous voulez (ex. Kinshasa → Johannesburg → Kinshasa → Le Caire), avec un bouton ↩️ Retour au départ ; le trajet complet s’affiche sur la ligne et le voyage illustré le suit jusqu’au bout. Avions : les trajectoires ne sont plus des lignes droites — chaque vol a sa courbe (un arc d’un côté ou de l’autre, parfois un S, parfois presque droit), l’aller et le retour prennent des chemins différents, et ça change selon les jours. La carte dessine l’aller et, en pointillés, le retour.'],
  ['🧬 L’éditeur va plus loin','Recherche par nom (tapez « Paris » ou « Nigeria »), bouton 🧬 Modifier sur chaque fiche d’aéroport, de pays et de compagnie, 🎬 Scénarios en un geste (Afrique en plein essor, Congo superpuissance, crise pétrolière, IA légendaire, mode zen, guerre ou paix mondiale, monde d’origine) annulables d’un coup, ✈️ vos avions un par un (nom, état, téléportation, changement de modèle), et 🌐 Code de monde pour copier et partager votre monde modifié.'],
  ['🚫 Plus de nouvelles compagnies automatiques','Le jeu ne crée plus de compagnies tout seul : ni au hasard, ni par vagues, ni quand vous agrandissez un aéroport (aucune compagnie ne vient s’y installer à cause de vos travaux). Dans 🧬 Éditeur → 🤖 IA : un interrupteur pour les réautoriser si vous voulez, et un bouton 🧹 pour supprimer d’un coup les petites compagnies inventées par le jeu.'],
  ['🎬 Revoir un accident au ralenti','Touchez un accident (💥 🔥 ⚠️ sur la carte, onglet 💥 Accidents des actualités, ou la fenêtre de votre propre accident) puis ▶️ : une vidéo reconstitue ce qui s’est passé, vue de côté, avec ralenti automatique aux moments clés, transcription du cockpit, altitude et vitesse, pompiers et évacuation par les toboggans, puis un rapport d’enquête. Scénarios : sortie de piste sous la pluie, atterrissage dur, feu moteur (chute ou retour réussi), orage et givrage jusqu’au décrochage, fumée en cabine. Reconstitution fictive.'],
  ['🧬 L’éditeur divin','Plus → 🧬 Éditeur divin : modifiez TOUT le jeu en direct, pendant qu’il tourne. Votre compagnie (argent, image, nom, couleur, limite de flotte), tous les avions (sièges, autonomie, vitesse, prix — même 1 $ —, consommation) et des avions sans aucune limite, les pays (nom, capitale, population, richesse, envie de voyager, guerre), les aéroports (nom, trafic, piste, population, fermeture), l’économie, le temps, et l’IA (niveau de Débutant à Légendaire, chaque compagnie, création et disparition). Un journal permet d’annuler chaque changement. ⚠️ Mais le monde vous surveille : trop de triche fait monter la vigilance mondiale — rumeurs, enquête et amendes, vos compatriotes et alliés se retournent contre vous, coalition mondiale, boycott des passagers, vassales qui ne paient plus.'],
  ['👑 Compagnies vassales','Quand vous achetez 51 % d’une compagnie (Compagnie → Bourse), vous choisissez : en faire votre VASSALE (elle garde son nom et ses avions, l’IA la dirige, et ses bénéfices vous sont versés chaque semaine — 100 %, ou 50 % pour qu’elle grandisse plus vite ; elle ne vous attaque jamais), ou l’INTÉGRER (vous dirigez ses avions, en achetez, en vendez, ajoutez des lignes). D’autres compagnies peuvent proposer de racheter votre vassale : c’est vous qui décidez. Une vassale peut être intégrée plus tard.'],
  ['🟡 Masambukidi Fly démarre petite','Masambukidi Fly redémarre avec 10 gros porteurs et ses 10 lignes depuis Goma, puis progresse peu à peu (environ une vingtaine d’avions au bout d’un an, image et sécurité qui montent chaque semaine). Les compagnies congolaises s’améliorent progressivement au lieu d’être fortes d’un coup, avec environ 2 lignes par avion. Les compagnies étrangères deviennent plus fortes aussi : elles apprennent de leurs bons résultats et les jeunes sont soutenues la première année.'],
  ['🇨🇩 Des compagnies congolaises vraiment fortes','Les compagnies de votre pays (et Masambukidi Fly) sont maintenant fortes dans tous les domaines : rentables et sans dettes, image parmi les meilleures du monde, flotte neuve et très sûre (moins d’accidents), bases à l’étranger, avantage dans les guerres des prix contre les étrangères, et rachat de compagnies étrangères en difficulté. Elles ne vous attaquent jamais. Leur classement mondial : 📰 Actualités → 🏁 Marchés.'],
  ['🟡 Masambukidi Fly','Nouvelle compagnie congolaise basée à Goma : 1 milliard de dollars de fonds, avions jaunes, uniquement de très gros porteurs (A380, 777, 747), 10 lignes vers les plus grandes villes du monde (Dubaï, Londres, Paris, Atlanta, Tokyo…). Elle s’étend chaque semaine et ouvre des bases à l’étranger, sans jamais vous faire la guerre. Toutes les compagnies de votre pays deviennent plus fortes, grossissent et partent à la conquête de l’étranger, sans vous attaquer. Et plus d’avions dans le ciel de la carte.'],
  ['🏁 La guerre des marchés','La bataille ne se fait plus par pays mais par marché (aéroport) : n’importe quelle compagnie peut venir se battre n’importe où — Qatar Airways à Kinshasa, une compagnie chinoise à Paris… Chacune veut dominer les marchés où elle vole et attaque celle qui est juste devant elle (nouvelles lignes, bases à l’étranger, guerres des prix), vous comprise, sans vous viser en particulier. La n°1 d’un marché se défend. Une compagnie chassée de toutes les lignes de son hub disparaît. Suivez tout dans 📰 Actualités → 🏁 Marchés. Vous pouvez aussi fermer un hub (🏢 Acheter un hub → Vos hubs → 🗑️ Fermer).'],
  ['🛫 Les terminaux servent vraiment','Vos avions utilisent maintenant les Terminaux 2, 3 et 4 que vous construisez : vols internationaux aux T2/T4, vols intérieurs aux T1/T3, avec portes, passerelles, aires de béton et roulage (T4 contourne T1). Le « vol présidentiel » est désormais un vrai aller-retour qu’on voit décoller, payé au retour ; un rappel constructeur met vraiment les avions au sol en atelier (🔧).'],
  ['🚨 Voyage : clignotants, feux de détresse, orages, personnages et voitures redessinés','Les véhicules ont maintenant des phares, des feux arrière et des clignotants orange : les voitures qui vous dépassent clignotent, votre camion met le clignotant en repartant d’un arrêt ou d’un feu, et allume ses feux de détresse au contrôle de police, à la douane, au péage, dans le bourbier ou en panne sèche. Le camion en panne sur le bas-côté a ses warnings et un triangle rouge. Orages plus forts à la saison des pluies : éclairs plus lumineux, palmiers couchés par le vent, essuie-glaces qui balaient le pare-brise, « ⛈️ orage » dans le bandeau. Les personnages sont redessinés : vraies jambes et bras avec coudes, chaussures, visage, cheveux, casquettes ; les mamans portent un pagne en wax et un foulard noué, avec leur bassine sur la tête ; le policier a son uniforme, sa casquette et son ceinturon. Les voitures et pick-up sont redessinés : carrosserie arrondie, pare-brise, montant de porte, poignées, pare-chocs, passages de roue.'],
  ['🏙️ Kinshasa en vrai, saisons, marché flottant et guide Transport','À Kinshasa : embouteillages où tout avance au pas (les wewa se faufilent, les vendeuses passent entre les voitures), bus « esprit de mort » jaunes et bleus avec le receveur accroché à la porte, tour de l’Échangeur de Limete au loin, Rond-point Victoire, et Brazzaville 🇨🇬 sur l’autre rive du fleuve. Les grandes villes ont leurs embouteillages et leurs places (Place de la Poste à Lubumbashi, Rond-point Signers à Goma…). Le voyage suit la vraie saison du jeu : beaucoup de pluie à la saison des pluies, presque pas à la saison sèche. En bateau, marché flottant de pirogues chargées de fruits à chaque escale. Les voyageurs ont des noms : « Maman Josée et Papa Didier descendent, Grâce et Fiston montent ». Nouveau guide « 📖 Comment ça marche ? » dans Transport et dans le Guide du jeu.'],
  ['⏭️ Voyage : étape suivante, décor allégé et décisions du chauffeur','Nouveau bouton ⏭️ : on saute directement au prochain arrêt, contrôle, station ou à l’arrivée. Bouton 🪶 « décor allégé » si votre téléphone rame ; il s’active tout seul si l’animation devient trop lente. Le voyage devient un petit jeu : au contrôle de police, payer 20 $ ou discuter (on peut passer sans rien payer… ou prendre une amende) ; le camion a une jauge de carburant ⛽ et s’arrête aux stations-service (faire le plein ou continuer, gare à la panne sèche) ; sur la piste, un bourbier : payer les jeunes pour pousser ou attendre ; en bateau, un banc de sable : alléger ou attendre la crue. Les péages coûtent 10 $. Ces frais sont vraiment payés par votre compagnie, et à l’arrivée, si vous êtes à l’heure (moins d’une heure de retard), vous touchez une prime de ponctualité.'],
  ['🦒 Voyage illustré : animaux, foot, vrais véhicules','Chaque véhicule a maintenant son vrai dessin : camionnette, porteur 12 t, semi-remorque, citerne de kérosène ; train minier vert avec wagons de cuivre et de cobalt, train rapide blanc. Des animaux : troupeaux de vaches avec leur berger (grandes cornes au Kivu et dans l’Est), girafes, zèbres et éléphants en Afrique de l’Est et australe, singes dans les grands arbres de la forêt, hippopotames dans les rivières, oiseaux posés sur les fils électriques qui s’envolent quand vous klaxonnez. Dans les villages : des enfants jouent au foot avec des petits buts. En ville : rond-point avec statue et drapeaux, grande tour au loin dans les capitales, guirlandes qui clignotent devant les bars la nuit. Au Sahel et au Sahara : l’harmattan, vent de sable qui jaunit le ciel.'],
  ['🚦 Vrais feux tricolores, gratte-ciel, bidonvilles et plages','Les feux passent au vert, à l’orange puis au rouge : votre camion s’arrête à l’orange et au rouge et attend le vert. Pendant votre rouge, les voitures de la rue qui croise passent (on les voit arriver en perspective), et les piétons traversent puis continuent leur chemin sur le trottoir ; une voiture d’en face attend aussi au feu. Dans les grandes villes (Kinshasa, Lagos, Johannesburg…) : gratte-ciel en verre avec reflets, enseignes et feu rouge sur l’antenne, fenêtres allumées la nuit. À l’entrée des grandes villes : bidonvilles de cabanes en tôle avec bâches bleues, pierres sur les toits, fûts d’eau et linge. Près de la mer (Muanda, Banana, Luanda, Pointe-Noire, Lagos, Dakar, Dar es Salaam, Durban…) : l’océan au loin avec reflets du soleil, plage avec parasols, baigneurs et pirogues, maisons de plage colorées avec terrasses et palmiers.'],
  ['🎥 Voyage illustré : effets de cinéma','La caméra zoome doucement sur votre véhicule quand il ralentit ou s’arrête (feu rouge, police, péage, douane, escale), puis recule quand il repart ; sur la piste, l’image tremble un peu avec les bosses. Orages sous les grosses pluies : éclairs dans le ciel et grondement du tonnerre. Brume du matin qui traîne au ras du sol au lever du soleil. Camion plus détaillé : portes et barres de fermeture, bande réfléchissante, jupe latérale, calandre, pare-soleil, marchepied, réservoir chromé, garde-boue, écrous de roue. Personnages avec cheveux et chaussures, enfants plus petits ; paraboles et climatiseurs sur les maisons.'],
  ['🎨 Voyage illustré encore plus riche','Plus de profondeur : un deuxième plan de villages et d’arbres entre le lointain et le bord de la route, un sol vivant (touffes d’herbe, buissons, cailloux, zones d’ombre). Petits nuages bas à l’horizon, rayons du soleil à l’aube et au coucher, halo orangé au-dessus des villes la nuit. Balises blanches au bord des routes goudronnées dont les catadioptres s’allument dans vos phares, reflet des phares sur la route la nuit, pneus plus détaillés, traînées de vitesse en ×50 et ×200.'],
  ['🌍 Camions et trains partout en Afrique, avec escales et voyageurs','Les camions peuvent maintenant aller dans toutes les villes d’Afrique où vont vos avions (387 villes, 49 pays — sauf les îles), et le train aussi en construisant une voie neuve. Nouveau : les ESCALES. Sur chaque ligne, touchez « ➕ Ajouter une escale » : le jeu propose les villes qui allongent le moins le trajet. À chaque arrêt, on décharge et on charge du fret, des voyageurs descendent et montent : plus d’arrêts = plus de clients. Nouveaux véhicules pour les VOYAGEURS : minibus 18 places et autocar 60 places (camions), train de voyageurs 600 places. Le tableau montre la demande de voyageurs et les places offertes. Dans le voyage illustré : autocar aux couleurs de votre compagnie avec bagages sur le toit et passagers aux fenêtres, abribus où les gens montent, wagons de voyageurs éclairés la nuit, douane avec les drapeaux à chaque frontière, et de nouveaux paysages (Sahara, Sahel, Afrique de l’Est, Afrique australe, Afrique de l’Ouest). Le dessin est un peu plus grand et les véhicules ressortent mieux.'],
  ['🗺️ Voyage illustré : chaque région du Congo a son décor, et les bateaux aussi','Le paysage change selon la région traversée : 🌴 Bas-Congo (collines vertes, fleuve, pont suspendu de Matadi), 🌾 Kwango-Kwilu (plateaux et champs de manioc), 💎 Kasaï (terre de sable, ravins d’érosion, creuseurs de diamants), ⛏️ Katanga (terrils noirs, chevalements de mine, camions-citernes et bennes jaunes), 🌋 Kivu (volcans qui fument et rougeoient la nuit, lac, collines de thé, eucalyptus), 🌊 Tanganyika (le grand lac), 🌳 Cuvette centrale (grande forêt, palmeraies), 🌾 Savane du Nord (hautes herbes, cases rondes). Chaque ligne a aussi ses propres villages et couleurs. Partout au bord des routes : vendeurs d’essence en bouteilles, sacs de charbon, brochettes qui fument, parasols « Crédit ». Nouveau : le voyage illustré en BATEAU — pousseur et barges chargées sur le fleuve avec jacinthes d’eau, pêcheurs en pirogue et escales dans les ports (grues, conteneurs), bateau de lac sur le Kivu et le Tanganyika, cargo porte-conteneurs en mer.'],
  ['🚦 Voyage en camion : feux rouges, autoroute et circulation dans les deux sens','En ville, le camion s’arrête aux feux rouges (feux tricolores des deux côtés, passage piéton où les gens traversent pendant que vous attendez), puis repart au vert. La route change : autoroute à 2×2 voies avec terre-plein central et lampadaires à la sortie des grandes villes (panneaux « Autoroute » et « Fin d’autoroute »), route à deux voies ailleurs, piste en terre sur les longs trajets. La circulation va dans les deux sens : des véhicules viennent en face, et d’autres vont dans votre sens et vous dépassent (par la voie de gauche sur l’autoroute). Le bandeau indique le type de route.'],
  ['🚚 Voyage illustré : la route prend vie','Pendant le voyage en camion, la route réserve des surprises : contrôle de police avec barrière (le camion freine, feux stop allumés, puis repart), péage, travaux avec cônes et ouvrier au drapeau, camion en panne sur le bas-côté avec des branches sur la route pour prévenir. Arrêt de livraison dans chaque ville étape. En train : passages à niveau avec feux rouges qui clignotent, barrières baissées et voitures qui attendent, arrêt en gare avec voyageurs sur le quai et chef de gare. Près des villes du fleuve (Kinshasa, Matadi, Kisangani, Mbandaka…) on voit le fleuve Congo au loin avec baleinières, barges et pirogues. Arc-en-ciel après la pluie. Touchez l’écran pour klaxonner : le chauffeur sort le bras et les gens au bord de la route vous saluent. Nouveaux boutons : 🔍 zoom, 📸 photo souvenir à partager, 🔊 sons (moteur, tac-tac du train, pluie, oiseaux le jour, grillons la nuit, klaxon).'],
  ['🖌️ Voyage illustré : graphismes refaits','Le voyage en camion ou en train est beaucoup plus beau : vraie lumière selon l’heure (aube dorée avec brume, coucher de soleil rose, nuit bleutée où brillent fenêtres, lampadaires et phares), ombres au sol, montagnes et collines en profondeur, champs et villages au loin. Pluies tropicales de temps en temps (flaques, gouttes sur la route). Les longues routes alternent goudron avec nids-de-poule et piste en latérite rouge avec poussière. Rivières en perspective avec pont et pirogue de pêcheur, pont métallique pour le train, gare à chaque arrêt. Villages : maisons en briques de terre et toits de paille, feu de cuisine, linge qui sèche, chèvres et poules, mamans avec bassines sur la tête. Villes : boutiques peintes (Alimentation, Pharmacie, Pagnes…), immeubles, station-service, kiosques, panneau publicitaire de VOTRE compagnie. Circulation : taxis-bus jaunes, motos-taxis, camions chargés de sacs et de passagers, vélos chargés de charbon. Bornes kilométriques jusqu’à la destination.'],
  ['🎨 Le voyage en camion ou en train devient un beau dessin','Fini les cubes : le bouton « 🎬 Voyage illustré » (sur chaque ligne de camion ou de train, et dans la fiche d’un camion) ouvre maintenant une vue de côté dessinée, comme un jeu mobile. Le ciel suit l’heure (lever du soleil, plein jour, coucher, nuit étoilée avec la lune), collines au loin, forêt équatoriale près de l’équateur et savane avec acacias et baobabs ailleurs, villages aux toits de tôle avec église et marché, petits kiosques, jardins publics avec bancs et lampadaires, immeubles dans les grandes villes, silhouette de la ville qui approche, panneau « Bienvenue à … », ponts sur les rivières, circulation en face. Votre camion ou votre train porte les couleurs de votre compagnie, phares allumés la nuit. Vitesse ×1 à ×200, et un résumé à l’arrivée.'],
  ['🎬 Voyage en 3D en camion ou en train','Nouveau bouton « 🎬 Voyage en 3D » sur chaque ligne de camion ou de train (et dans la fiche d’un camion) : la caméra suit votre véhicule sur toute la route, de la ville de départ à la ville d’arrivée. Le décor se construit au fil du voyage : route goudronnée avec marquage ou voie ferrée, palmiers, manguiers, acacias, poteaux électriques, villages avec maisons à toit de tôle, église, marché au bord de la route, terrain de foot, champs, petites villes aux arrêts, et la circulation en face. Vitesse ×1, ×10, ×50 et 4 caméras (derrière, côté, drone, devant). Près de Kinshasa, la vraie ville 3D apparaît en plus.'],
  ['👥 Jouer entre amis','Nouveau dans 🏢 Compagnie → 👥 Amis : partagez votre carte de score par WhatsApp ou SMS (un code SKY1-…), collez celui de vos amis, et comparez-vous dans un classement entre amis. Chaque semaine, un défi est le même pour tout le monde (passagers, vols, fret, bénéfice, nouvelles lignes) : qui fera le plus depuis lundi ? Sans compte ni serveur.'],
  ['🚚 Vos camions en 3D, à toucher','En 3D, près d’une ville de vos lignes de camions (Kinshasa, Matadi, Lubumbashi…), vos camions roulent sur les vraies routes, aux couleurs de votre compagnie. Touchez-en un : chauffeur, chargement, ligne, résultats, état du camion. « 🎥 Suivre en 3D » : la caméra roule derrière lui sur la route congolaise. Sur la carte 2D aussi, touchez un 🚚 pour voir sa fiche.'],
  ['🛤️ Camions et trains dans toutes les villes','Les camions peuvent aller dans toutes les villes de la RDC desservies par avion (plus de limite de distance) ; on peut ouvrir un dépôt dans n’importe laquelle. Les trains aussi : « Construire une nouvelle voie ferrée » relie n’importe quelle ville à la gare la plus proche (350 000 $ par km) ; la ville devient une gare de votre réseau, avec une voie neuve rapide et sûre.'],
  ['⚔️ Duels sur vos lignes','En haut de 🏢 Compagnie → ⚔️ Concurrents : pour chaque ligne disputée, votre part de marché, vos prix, et ce que fait chaque concurrent (il aligne ses prix, ajoute des vols, casse ses prix, remonte ses tarifs…). Ripostez en un geste : prix −10 %, +10 %, ou gérez la ligne.'],
  ['⚡ Événements en vol : à vous de décider','De temps en temps, un de vos avions en vol vous pose un problème : alarme moteur, orage sur la route, passager malade, ministre qui veut réquisitionner l’avion, célébrité qui veut un surclassement. Le jeu se met en pause et vous choisissez ; chaque choix a ses conséquences (argent, image, retards, gouvernement). Bouton « Voir l’avion ». Sans réponse en 90 s, le commandant prend la décision prudente. Fréquence réglable (désactivés, rares, normaux, fréquents) dans 🏢 Compagnie → ⚙️ Réglages.'],
  ['🎯 Campagne de missions','12 missions vous guident de petite compagnie à géant du continent : premières lignes, désenclaver le pays, clients contents, salon VIP, équipage d’élite, ami du gouvernement, une ville qui grandit, groupe de transport, toutes les provinces, le fleuve, top 50 mondial, première compagnie du continent. Chaque mission réussie rapporte de l’argent et de l’image (à récupérer). Bouton « Comment ? » pour savoir où aller. Dans 🏢 Compagnie → 🎯 Missions (ou Plus).'],
  ['🛟 3D : fini l’écran figé','Correction importante : après quelques petites erreurs d’affichage sur une longue session, la 3D pouvait s’arrêter de bouger. Maintenant, une erreur isolée est corrigée toute seule et la 3D continue ; si les erreurs s’enchaînent, la 3D se ferme proprement avec une explication (et le 🩺 Diagnostic garde la trace).'],
  ['🚢 Bateaux sur le fleuve en 3D','À Kinshasa, la 3D montre maintenant la vie sur le fleuve : pirogues, bateaux de passagers entre Kinshasa et Brazzaville, convois de barges qui remontent le Pool Malebo. Si votre filiale 🚢 a des barges sur le fleuve, elles apparaissent aussi, avec des conteneurs à la couleur de votre compagnie.'],
  ['⚡ Jeu 2 fois plus rapide avec une grosse flotte','Avec près de 300 avions, la simulation tourne environ 2 fois plus vite : le rattrapage au retour dans le jeu est plus court et le téléphone chauffe moins. (Les comptes d’équipages et de personnel sont calculés une seule fois par instant, et les avis de passagers sont tirés plus intelligemment.)'],
  ['🚆 Filiale trains','Troisième filiale : des trains sur le vrai réseau ferré congolais. Matadi–Kinshasa, le réseau du Katanga et du Kasaï (Lubumbashi, Likasi, Kolwezi, Kamina, Kananga, Ilebo, Kabalo, Kalemie, Kindu), Kisangani–Ubundu, et les sorties vers Lobito (Angola) et Ndola (Zambie). Le cuivre et le cobalt du Katanga doublent la demande. Trains de marchandises, trains miniers et trains rapides. Les voies sont vieilles : lentes et déraillements possibles ; « Réhabiliter la voie » rend la ligne 70 % plus rapide et bien plus sûre.'],
  ['🚚🚢 Filiales camions et bateaux','Votre compagnie devient un groupe de transport. 🚚 Camions : du fret vers toutes les villes de la RDC (routes goudronnées rapides Kinshasa–Matadi–Kikwit, Katanga, Goma–Bukavu ; pistes lentes, coupées par les pluies ; barrières et risques dans l’Est). 🚢 Bateaux : barges sur le fleuve Congo et le Kasaï (Kinshasa ⇄ Mbandaka, Kisangani, Ilebo, Bangui, Brazzaville), bateaux sur les lacs Kivu et Tanganyika, caboteurs de Matadi vers Anvers, Lagos, Durban, Dubaï, Shanghai… Ouvrez des dépôts et des ports, achetez des véhicules, ouvrez des lignes : la liste propose les plus rentables. Les lignes et les véhicules se voient sur la carte. Dans 🏢 Compagnie → 🚚 Transport (ou Plus).'],
  ['🏛️ Vos vols font grandir le pays','Chaque passager transporté vers une ville de votre pays la fait grandir : plus d’habitants et plus de voyageurs. Par paliers (5 000, 25 000, 100 000, 400 000 passagers), l’État bitume ou allonge la piste, agrandit le terminal, puis vous verse une prime. Chaque mois, le gouvernement juge votre compagnie (villes desservies, petites villes, pilotes du pays, ponctualité, accidents, grèves) : subvention et taxes réduites si vous êtes bien vu, taxe spéciale sinon. Tout est dans 🏢 Compagnie → 🏛️ Mon pays, avec la liste des villes et un bouton pour y ouvrir une ligne.'],
  ['👨‍✈️ Vos pilotes sont des personnes','Chaque pilote a un grade (copilote, commandant, instructeur, chef pilote), des heures de vol qui montent quand il vole, et son propre moral. Promouvez ceux qui le méritent, nommez un chef pilote. Un pilote expérimenté et mécontent peut être débauché par un concurrent : un message 📬 vous permet de le retenir. Si le moral est trop bas, le syndicat envoie un préavis de grève (augmentation, prime ou refus). Parfois, un pilote réalise un exploit. Tout est dans 🏢 Compagnie → 👨‍✈️ Équipages. En mode simple, les promotions se font toutes seules.'],
  ['🛟 3D plus légère sur iPhone','Kinshasa en 3D charge moins de maisons et de quartiers à la fois sur téléphone (la ville se remplit autour de l’endroit regardé). Nouvelle « boîte noire » : si la 3D s’arrête, le 🩺 Diagnostic 3D (dans Plus) indique ce qui était affiché juste avant. Envoyez-en une capture pour aider à corriger.'],
  ['🏢 Nouvel onglet « Compagnie »','Tout ce qui concerne votre compagnie est rangé au même endroit, en 7 parties expliquées : Résumé (ce qui va bien, quoi faire ensuite), Améliorer (service à bord, programme de fidélité, salons VIP, terminaux et équipements de chaque hub), Clients (notes, raisons des mécontentements, VIP qui vous écrivent), Concurrents (toutes les compagnies IA, celles présentes sur vos lignes, partage de codes, rachat), Espace aérien (fermer votre ciel à toutes les compagnies étrangères ou pays par pays, fermetures dans le monde), Partenaires et Réglages.'],
  ['🎓 Tutoriel refait','Un écran de bienvenue, puis 7 étapes expliquées (9 en mode expert) qui font découvrir les lignes, les vols, la compagnie, les clients, les améliorations et les concurrents. Touchez le texte du bandeau pour lire toute l’explication. Nouveau 📖 Guide du jeu complet, dans « Plus ». Correction : fermer l’espace aérien plantait si la 3D n’avait pas été ouverte.'],
  ['🏙️ Tout Kinshasa en 3D','La ville est maintenant rangée dans le jeu : environ 45 000 vrais bâtiments, les grandes routes, parcs, marchés, églises, écoles et hôpitaux de toute la ville (Gombe, Lemba, Masina, Kintambo, Ndjili…), sans attendre les serveurs publics souvent en panne. Les quartiers se remplissent de maisons basses à la densité réelle de chaque quartier (comptée dans OpenStreetMap ; leurs formes exactes sont simplifiées). Données © contributeurs OpenStreetMap, licence ODbL.'],
  ['⛪ Kinshasa jusqu’à l’aéroport','En 3D, la ville détaillée va maintenant du fleuve jusqu’à N’djili (Limete, boulevard Lumumba, Masina). Églises avec clocher, mosquées avec minaret, hôpitaux et écoles avec leur nom, icônes des stations-service, banques et hôtels (données OpenStreetMap). La nuit, les lampadaires s’allument le long des avenues et boulevards. Sur téléphone, seuls les quartiers proches de ce que vous regardez restent chargés.'],
  ['🛟 3D allégée sur téléphone','La ville en 3D faisait planter l’iPhone (trop de bâtiments en mémoire). Sur téléphone : environ 4 fois moins de bâtiments (surtout au bord du fleuve), pas de toits en pente, moins d’arbres et de voitures, fleuve dessiné plus simplement. Si la 3D plante quand même, le jeu le détecte et allège encore la ville au lancement suivant.'],
  ['🌊 Le fleuve et la ville enfin visibles','Correction : avec le relief activé, les bâtiments, arbres, monuments et voitures étaient posés à 0 m, donc enterrés sous Kinshasa (≈ 300 m d’altitude) — la ville ne s’affichait pas. L’altitude est maintenant lue dans les tuiles de relief. Et le fleuve Congo (Pool Malebo, rapides de Kintambo) est dessiné en vraie eau animée avec reflets, entre Kinshasa et Brazzaville.'],
  ['🌊 Les deux rives du fleuve','Près de Kinshasa en 3D, les quartiers au bord du fleuve Congo se chargent en priorité et restent affichés : Kinshasa en détail (Gombe, Kintambo, Lingwala, Barumbu…) et la rive de Brazzaville en face (Plateau, Poto-Poto, Bacongo, Tour Nabemba). Le reste de la ville se charge autour de ce que vous regardez, sans doublons.'],
  ['🏙️ Gombe plus vrai','Testé sur les vraies données OpenStreetMap de Gombe : hauteurs plus réalistes (surtout des immeubles de quelques étages, peu de tours inventées), murs peints de couleurs variées (crème, beige, ocre, pastel), toits-terrasses en béton, et noms des bâtiments connus au-dessus des toits (hôtels, galeries, immeubles…). Serveur de carte de secours ajouté pour charger la ville plus souvent.'],
  ['🌳 Parcs, marchés et monuments','En 3D, les parcs, jardins, forêts et cimetières (OpenStreetMap) sont verts avec des arbres et des palmiers ; les marchés ont leurs étals sous bâches colorées. Monuments de Kinshasa modélisés avec leur nom : Stade des Martyrs, Palais du Peuple, Tour de l’Échangeur, cathédrale, gare, mausolée… (et ceux des autres grandes villes).'],
  ['🏢 Vrais bâtiments en 3D','Les bâtiments ne sont plus des cubes : façades avec étages, fenêtres et vitrines, tours vitrées, maisons avec toits de tôle à 4 pans (rouille, gris, bleu, rouge) ; la nuit, une partie des fenêtres s’allume. Routes en asphalte avec ligne blanche, accotements clairs sur les autoroutes.'],
  ['🏙️ Kinshasa en grand, 3D plus nette','La ville se charge autour de ce que vous regardez (environ 20 × 20 km sur téléphone, 26 × 26 km sur ordinateur), plus seulement sous l’avion suivi ; bâtiments pleins avec toits. Autoroutes et nationales chargées sur ~45 km. Voitures, camions et bus plus gros et plus détaillés (vitres, phares, roues), toujours autour de vous. Image 3D plus nette en Minimal et Éco.'],
  ['🛣️ Routes, voitures et mini-carte en 3D','Près du sol, les vraies routes (autoroutes, nationales, avenues d’OpenStreetMap) apparaissent avec des voitures et des bus qui roulent. Une mini-carte en bas à droite montre où vous êtes et dans quelle direction vous regardez : ⤢ change sa taille, + / − zoome, 🎯 revient au zoom automatique, × la masque ; touchez-la pour y envoyer la caméra.'],
  ['🏙️ 3D plus vivante','Aéroports en 3D : hangars aux couleurs de votre compagnie, gare cargo et conteneurs, dépôt de carburant, parkings pleins de voitures, hôtels, route bordée d’arbres. Villes (bâtiments OpenStreetMap sous l’avion suivi) : tours au centre des grandes villes, toits de tôle, fenêtres allumées la nuit. Tout est dessiné en un seul bloc pour rester léger ; en qualité Minimal, voitures et arbres sont retirés.'],
  ['🚀 Grosses compagnies plus fluides','Avec des centaines d’avions et de lignes, la carte devenait trop lourde pour un téléphone : lignes dessinées sans animation au-delà de 25 lignes, seuls les avions à l’écran sont mis à jour, pas d’ombre sous les avions au-delà de 60 avions, objectifs et panneaux calculés une seule fois. Environ 3 fois plus d’images par seconde.'],
  ['⏩ Rattrapage d’absence débloqué','Au retour, le jeu simule votre absence en détail pendant au plus ~12 secondes, puis estime le reste d’après votre bénéfice moyen. Le bouton « Passer » marche tout de suite.'],
  ['⚡ Le jeu ne se fige plus','Le calcul des espaces aériens fermés ralentissait tout le jeu (surtout avec beaucoup d’avions) : il est maintenant mis en cache, environ 10 fois plus rapide.'],
  ['🛡️ 6 mois d’avance quand vous agrandissez','Après un chantier, aucune nouvelle compagnie ne s’installe dans cet aéroport pendant 6 mois, plus aucune compagnie créée exprès ; au plus une compagnie peut venir après 4 mois.'],
  ['⚔️ Guerre = ciel fermé','Un pays en guerre ferme son espace aérien aux compagnies étrangères : vols vers ce pays interdits, et les lignes qui le survolent font un détour (visible sur la carte).'],
  ['🛫 Les trajets de chaque compagnie','Fiche d’un aéroport : touchez une compagnie du classement (ou la vôtre) pour voir ses trajets depuis cet aéroport, ses vols et ses passagers par jour, et où elle est ⚔️ face à vous. Vos passagers ne font plus disparaître les autres compagnies des petits aéroports.'],
  ['🗺️ Détours d’espace aérien visibles','Une ligne qui traverse un espace fermé est maintenant détournée autour du territoire : durée, distance, avion rival et tracé vert suivent la route de contournement en 2D comme en 3D. Une liaison vers un aéroport interdit reste bloquée.'],
  ['🛂 Choisir qui survole votre pays','Dans la fiche Monde → votre pays → Espace aérien, interdisez le survol aux compagnies de certains pays. Le choix est sauvegardé ; les avions existants et futurs prennent le détour. Les interdictions géopolitiques déjà actives restent prioritaires.'],
  ['✈️ Détails des avions sur la carte','Touchez un avion concurrent pour voir sa ligne directe, sa position et sa progression, le modèle et la capacité estimés, la fréquence, la part de marché et les passagers estimés par vol. La fiche reste ouverte jusqu’au déplacement/zoom, au toucher d’un autre avion ou à un second toucher sur le même. Les passagers des concurrents sont une estimation de marché, pas un manifeste réel.'],
  ['⛔ Fermetures géopolitiques','Les compagnies américaines contournent l’Iran, les compagnies russes contournent l’Ukraine, et les compagnies rwandaises ne survolent pas la RDC, la Corée du Nord, le Soudan, la Palestine, l’Iran ni l’Ukraine. En Corée du Nord, seules les compagnies chinoises, russes, congolaises et nigérianes restent autorisées.'],
  ['🛫 Jeunes compagnies enfin actives','Les startups ouvrent des lignes même quand leur trésorerie est négative; le coût reste comptabilisé et les pertes ne sont pas effacées. Une tentative supplémentaire revient tous les 3 jours par startup, avec au plus une ouverture tentée par jour de simulation pour préserver la fluidité. Elles peuvent encore faire faillite après leur première année si leur réseau ne fonctionne pas.'],
  ['🇨🇩 Air Kivu développe enfin son réseau','Air Kivu profite de la même priorité d’expansion que les autres jeunes compagnies, avec des destinations régionales accessibles depuis Bukavu. Elle ne reçoit pas d’argent illimité pour masquer ses pertes; son résultat hebdomadaire détermine ensuite sa survie.'],
  ['⛽ Carburant et entretien automatiques','Pour les parties existantes et nouvelles, l’achat de carburant et la maintenance des avions sont activés automatiquement par défaut. Le seuil de ravitaillement automatique est réglé à 0,90 $/L; les IA comptabilisent également carburant et maintenance dans leurs finances.'],
  ['🌙 Nuit et neige en vue 3D','Le bouton du soleil fait défiler Auto (heure du jeu), Jour et Nuit. Un bouton Neige active une chute de flocons légère, sans modèle ni ressource distante, désactivée par défaut. Les deux préférences sont mémorisées.'],
  ['✈️ Voyageurs en RDC : grandes villes revalorisées','Les portes des grandes villes ont un minimum de 20 M de voyageurs par an : Kinshasa 48 M, Goma 35 M, Lubumbashi 20 M, ainsi que les autres villes de plus d’un million d’habitants. Les villes moyennes et petites ont des planchers gradués selon leur population (5 M, 2 M ou 100 000 à 300 000). Ces valeurs alimentent aussi le marché aérien; elles restent adaptables à la hausse selon le trafic existant.'],
  ['🇨🇩 Air Kivu part de Bukavu','Air Kivu démarre avec 5 avions et 2,5 Md$ de fonds. Son hub de Bukavu dispose d’une piste revêtue de 4 200 m, classe 5. Les chiffres passagers intègrent aussi l’évolution démographique et économique.'],
  ['🌍 Jeunes compagnies dans les pays défavorisés','Pendant quatre mois de jeu, une nouvelle jeune compagnie peut naître tous les 30 jours dans chacun des 79 pays déjà représentés à revenu faible ou moyen inférieur. Panama est inclus à ta demande ; aucun aéroport n’est ajouté aux pays absents du jeu.'],
  ['⚖️ Réaction mesurée aux agrandissements','Après un chantier d’aéroport, une compagnie existante peut aussi ouvrir une ligne vers l’aéroport. Les réactions aux lignes restent espacées d’au moins 3 jours de jeu.'],
  ['🇨🇩 120 M d’habitants, 4 terminaux en 3D','Accueil : habitants du pays, voyages en avion par an, et classement des villes (habitants, voyageurs, vos passagers). Kinshasa, Lubumbashi et Goma deviennent de grandes portes (6 M, 3 M et 2,5 M de voyages par an au départ), les autres villes suivent leur population. Agrandissement en 7 étapes avec Terminal 3 et Terminal 4 ; pistes allongées, 2ᵉ piste et terminaux visibles tout de suite en 3D et sur la carte 2D.'],
  ['🏛️ L’État construit, la diaspora voyage','Le gouvernement de votre pays goudronne et allonge les pistes des villes et vous propose des contrats pour ouvrir la ligne (courrier). Saisons de la diaspora (Noël, juillet-août) : demande +35 % vers l’Europe et l’Amérique. Les villes qui grandissent attirent plus de voyageurs.'],
  ['🕓 Horaires de départ au choix','Planning avion → choisissez une heure locale par ligne. Les pointes attirent plus de demande mais renforcent la concurrence ; les retours bien alignés sur les départs d’un autre vol améliorent les correspondances. L’ATC gère les conflits de piste ; « Automatique » conserve la répartition habituelle.'],
  ['🇨🇩 Congo plus grand, IA qui s’améliore','108 aéroports en RDC (65 nouvelles villes) avec leur population qui grandit. Pistes allongées jusqu’à la classe 5 et piste géante de 4 000 m pour l’A380 (immédiat). Plus de 120 compagnies IA dans le monde. Les rivaux ne copient plus vos lignes : ils s’améliorent (nouvelles destinations à eux, flotte moderne, service, fidélité, travaux dans leur hub).'],
  ['⚔️ Un vrai concurrent chez vous','Votre <b>rival national</b> grandit avec vous, copie vos meilleures lignes et casse ses prix (carte sur l’Accueil). Les chantiers d’aéroport (piste, terminal, agrandissement) sont <b>immédiats</b>. Ailleurs, États et rivales agrandissent leurs propres aéroports selon leurs décisions, sans réaction forcée à vos travaux. Population du pays et de la région sur la fiche aéroport.'],
  ['📈 Classements vivants + vitesse Lent','Fiche d’un aéroport : la demande du pays (essor, récession, saison, guerre) fait monter ou baisser le trafic, et les parts des compagnies bougent chaque semaine selon leurs décisions (IA) — flèches ▲▼ sur une semaine. Nouvelle vitesse <b>Lent</b> : une heure de jeu toutes les 2 minutes.'],
  ['🛫 Qui vole vraiment ici','Fiche d’un aéroport : classement en direct de toutes les compagnies présentes, <b>la vôtre comprise</b> (⭐) — destinations, vols et passagers par jour, part de marché, recettes par jour, situation (expansion, crise, guerre, faillite). Estimations calées sur le trafic réel de l’aéroport.'],
  ['📈 Classements vivants + vitesse Lent','Fiche d’un aéroport : la demande du pays (essor, récession, saison, guerre) fait monter ou baisser le trafic, et les parts des compagnies bougent chaque semaine selon leurs décisions (IA) — flèches ▲▼ sur une semaine. Nouvelle vitesse <b>Lent</b> : une heure de jeu toutes les 2 minutes.'],
  ['🛫 Qui vole vraiment ici','Fiche d’un aéroport : classement en direct de toutes les compagnies présentes, <b>la vôtre comprise</b> (⭐) — destinations, vols et passagers par jour, part de marché, recettes par jour, situation (expansion, crise, guerre, faillite). Estimations calées sur le trafic réel de l’aéroport.'],
  ['⏱️ Notifications et vitesses','Le jeu s’ouvre en Réaliste s’il était resté en Turbo/Ultra. Sur téléphone, les notifications s’affichent en bas (elles ne cachent plus les boutons de vitesse) ; en Rapide, Turbo et Ultra, seules les importantes apparaissent.'],
  ['🐢 Ultra ne fige plus le jeu','Avec une grande flotte, le téléphone ne suivait pas la vitesse Ultra et le jeu s’emballait jusqu’à se figer. Maintenant le calcul a un budget : le jeu ralentit un peu (« 🐢 limité par l’appareil ») mais reste fluide.'],
  ['🧠 Concurrents plus réalistes','Le résultat hebdomadaire dépend du réseau, des lignes réellement exploitées, du pays, du carburant, de la réputation, de l’âge et de la dette. Les compagnies fragiles peuvent restructurer, être rachetées ou faire faillite ; les rachats coûtent vraiment de l’argent et règlent votre participation.'],
  ['📊 Parts passagers expliquées','La part affichée porte sur les 70 routes les plus demandées, pas sur tous les voyageurs du pays. Le panneau sépare votre part de ce volume, votre part sur les routes directes desservies, les routes sans vol direct identifié et la couverture de l’échantillon. Les correspondances ne sont pas inventées.'],
  ['🧳 Contrôle passagers avec choix réels','Passagers → choisissez Économique (attractivité −5 %, satisfaction −5), Équilibrée (neutre) ou Assistance+ (+2,50 $ par passager et par tronçon, attractivité +8 %, satisfaction +6). Les frais et les avis des prochains vols suivent ce choix.'],
  ['🧑‍✈️ Équipe d’escale pour vos hubs','Dans la fiche d’un hub, investissez dans une équipe d’escale : rotations −15 %, retards de congestion −40 %, avec un entretien mensuel affiché.'],
  ['🛠️ Reprise de partie réparée','Le jeu rouvrait l’écran « Fondez votre compagnie » par-dessus votre partie : corrigé. Les très grosses compagnies se chargent sans limite de temps, et « Reprendre » ouvre la partie directement.'],
  ['🏗️ Agrandir vos aéroports','Plus → <b>🏗️ Agrandir mes aéroports</b> : dans les pays où vous avez un hub, 5 étapes (extension du terminal, jetée, 2e piste, Terminal 2, ville aéroportuaire). Plus de voyageurs, plus de portes, une piste réservée aux arrivées (moins de retards), avions plus gros, et l’aéroport grandit en 3D.'],
  ['🪶 3D stable sur iPhone','Sur téléphone, la 3D démarre en mode Minimal (sans relief ni nuages) pour ne plus couper ; ⚙️ dans la 3D pour essayer Éco ou Haute. Correction : en Minimal, avions et aéroports flottaient au-dessus du sol.'],
  ['📱 3D beaucoup plus légère sur téléphone','Mémoire graphique réduite (pas d’anticrénelage du tampon principal, transparence simplifiée, mode 3D seul). Si la 3D se ferme quand même, une fenêtre explique pourquoi et propose de voir les avions en 🏙️ Ville 3D, plus légère.'],
  ['🛠️ Démarrage réparé','Après une longue absence, le jeu s’affiche tout de suite et rattrape le temps passé en arrière-plan (barre de progression, bouton ⏭️ Passer) au lieu de rester bloqué sur un écran vide.'],
  ['📡 Le monde réel en direct','Vue 3D → <b>📡 Trafic réel</b> : les vrais avions en vol en ce moment autour de la caméra (bleu clair, heure réelle). <b>🌧️ Radar réel</b> : la vraie pluie (carte 2D aussi, dans ☰ Carte). <b>🌀 Cyclones réels</b> sur la carte et en 3D ; un vrai cyclone près de vos aéroports peut les fermer 24 h. État des sources dans Actus → 🌍 Monde.'],
  ['👁️ Vision « œil de Dieu »','En vue 3D : bouton <b>👁️</b> pour la caméra thermique FLIR (noir et blanc ou couleur), la vision nocturne, l’écran CRT ou le noir ; <b>🎯 Détection</b> encadre chaque avion avec son identifiant, son altitude et sa vitesse ; <b>📡 Contacts</b> liste les avions autour (touchez un des vôtres pour le suivre). Effets adaptés du projet libre God’s Eye View (licence MIT).'],
  ['✈️ Missions réelles','Guerre ou catastrophe : le président vous demande un avion (📬). Choisissez-le : il quitte vraiment ses lignes, décolle, se pose dans le pays en crise et ramène les évacués (visible sur la carte, en 3D, liste de passagers). Payé à chaque retour. Valise perdue : elle voyage sur votre prochain vol. Surréservation : les passagers prennent des sièges sur votre vol suivant.'],
  ['🎬 Directeur du monde','Une IA fait vivre la planète : population et richesse des pays, essor et récessions, guerres qui ferment l’espace aérien (réfugiés vers les voisins), séismes, cyclones, éruptions, épidémies… et des missions d’évacuation payées (📬). Elle dose le rythme selon votre partie. Actus → <b>🌍 Monde</b>.'],
  ['🪶 3D qui ne se coupe plus','Si le téléphone manque de mémoire graphique, la 3D se relance toute seule en mode <b>Minimal</b> au lieu de se fermer. Plus → Options → 🌍 Vue 3D : mode Minimal et 🩺 Diagnostic 3D.'],
  ['🛬 Décollages et atterrissages réparés','Sol de nouveau précis autour des pistes ; si le téléphone a un souci d’affichage, l’aéroport passe en version allégée au lieu de disparaître ; « Voir décoller / atterrir » attend moins longtemps.'],
  ['📱 3D allégée sur téléphone','Mémoire réduite d’environ un tiers : 30 images/s en Éco, moins d’avions et de décor au loin, carte 2D en pause pendant la 3D, sauvegarde moins fréquente, villes Google 3D allégées (et coupées si la 3D a planté).'],
  ['🛠️ 3D plus stable','Sur téléphone, la 3D démarre en <b>Éco</b> (plus fluide, moins de mémoire). Si elle se ferme toute seule, le jeu repasse en Éco automatiquement. ⚙️ en 3D pour changer.'],
  ['📰 À la une','En haut de la carte : les grandes nouvelles (présidents, accidents, attaques des rivaux). Touchez pour lire. Actus → <b>🏛️ Présidents</b> et <b>💥 Accidents</b>.'],
  ['🎬 Voir décoller / atterrir','Sur la carte 2D et dans 🛫 Mes vols : un bouton ouvre la 3D au moment du prochain décollage ou atterrissage.'],
  ['🧠 Duel sur vos lignes','Les compagnies présentes sur vos lignes réagissent chaque semaine : elles s’alignent sur vos prix, ajoutent des vols, ou remontent leurs tarifs. Détail d’une ligne → « Ce que font vos concurrents ».'],
  ['✈️ Concevoir mon avion','Plus → <b>✈️ Concevoir mon avion</b> ; et 13 nouveaux modèles (L-410, MA60, 727, Tu-154, A300F, 747-400F…).'],
  ['🧳 Passagers','Nouvelles rubriques : son séjour (programme, hôtel, budget) et ce vol en chiffres (distance, CO₂, miles, avis).'],
  ['🎮 Tour de contrôle en direct','Accueil : suivi des vols actifs, étape, progression et nombre de passagers, avec accès direct au suivi et au manifeste.'],
  ['🛂 Contrôle des passagers plus poussé','Arrivées en cours par pays, estimations d’assistance et de vérifications, recherche de fiches et filtres par profil dans les manifestes. Les voyageurs et contrôles sont simulés.'],
  ['🏆 Classements plus détaillés','Nouveau tri par croissance patrimoniale sur environ quatre semaines ; le classement des aéroports distingue désormais trafic de base, flotte et lignes du joueur et des IA.'],
  ['🌍 Classements plus vivants','Le classement mondial des compagnies se trie par patrimoine, flotte, réseau, passagers ou réputation. Le rang d’influence des aéroports tient maintenant compte des avions et lignes présents, en plus du bonus de scénario de Kinshasa.'],
  ['🛂 Passagers plus pertinents','Les raccourcis de pays suivent désormais les principales provenances de la destination choisie, au lieu d’afficher une liste figée.'],
  ['⚙️ Vue 3D plus sûre','La qualité Auto est équilibrée dès le lancement ; le mode Éco est choisi par défaut sur mobile pour limiter les plantages.'],
  ['📰 Actualités et présidents','Les boutons toujours visibles en haut ouvrent directement le fil des actualités ou les décisions des présidents.'],
  ['⚙️ Vue 3D plus fluide','Le réglage « Éco » réduit maintenant vraiment le nombre de pixels rendus pour soulager les appareils mobiles.'],
  ['⏩ Progression hors ligne','La partie avance maintenant à la vitesse choisie en votre absence (plafond ×60 et 30 jours), sauf si vous l’avez mise en pause.'],
  ['🤝 Concurrents plus vivants','Les jeunes compagnies ont davantage de chances de grandir ; les compagnies en difficulté peuvent être rachetées plus tôt par un concurrent solide.'],
  ['⚔️ Concurrence renforcée','Les nouvelles parties et les anciennes sauvegardes sans réglage démarrent en mode Impitoyable. Les challengers investissent davantage et leurs changements de flotte/réseau sont mieux synchronisés. Vous pouvez choisir Calme, Normale ou Féroce à tout moment.'],
  ['📈 Créations, rachats et faillites','Davantage de jeunes compagnies peuvent entrer sur le marché avec un capital proportionnel à leur flotte, grandir puis devenir des transporteurs établis. Les rachats de compagnies fragiles sont plus fréquents. Les grandes compagnies ne sont plus automatiquement sauvées : l’aide publique est conditionnelle, limitée à une seule fois et impose une réduction de flotte et de lignes.'],
  ['🌍 Pays qui pèsent sur les compagnies','Les périodes de crise et de boom affectent aussi les résultats des transporteurs IA, en plus de la demande et des restrictions déjà appliquées aux vols.'],
  ['📷 Photos des avions plus justes','Le jeu demande des pages photo plus précises par modèle/variante. En attendant la photo, il affiche une silhouette plutôt qu’une photo de famille potentiellement trompeuse.'],
  ['🗺️ Fond de carte 3D','En vue 3D : bouton <b>🗺️ Fond</b> (satellite, Sentinel-2, plan, relief, sombre…).'],
  ['🛫 Décollage / 🛬 atterrissage','En vue 3D sans avion suivi : <b>Prochain décollage</b> et <b>Prochain atterrissage</b>.'],
  ['🗓️ Calendrier des vols','Bouton <b>🗓️ Calendrier</b> (onglet Lignes, ou la liste des vols) : la semaine quadrillée, un bloc par rotation.'],
  ['⏩ Vitesses Turbo et Ultra','En haut : <b>Turbo</b> (un jour en 24 s) et <b>Ultra</b> (un jour en 3 s) pour que les jours passent vite.'],
  ['✈️ 17 nouveaux avions','Onglet <b>Acheter</b> : PC-12, Fokker 100, MD-83, DC-10, A310, Il-96, 747-200…'],
  ['💥 Accidents','Carte 2D et 3D : 💥 🔥 ⚠️ au lieu d’accident ; fiche d’une compagnie dans <b>Actus → Sécurité</b>.'],
  ['🏛️ Pays et présidents','Actus → 🏛️ Pays : chaque pays a un président qui commande des avions, change les taxes, ferme son ciel… et vous écrit (📬) pour des contrats.'],
  ['⚠️ Accidents','Votre flotte peut avoir des accidents (rares) : entretenez vos avions ! Niveau réglable dans Plus → Options.'],
  ['⚔️ Rivalité','Actus → Classement : les 3 plus grosses compagnies se mobilisent pour vous détrôner (levées de fonds, commandes record, guerres des prix, rachats). Réglable dans Plus → Options.'],
  ['🧑‍🤝‍🧑 Passagers','Touchez un vol → <b>📋 Passagers</b> → un passager : carte d’embarquement, bagages, santé, contact…'],
  ['🌊 Mers, 🌙 nuit','Vagues et reflets en 3D ; la nuit, villes et aéroports éclairés.'],
];
MODALS.whatsnew=()=>showModal('🆕 Nouveautés (version '+GAME_VER+')', `<ul class="inst">${WHATS_NEW.map(([a,b])=>`<li><b>${a}</b><br><span class="small">${b}</span></li>`).join('')}</ul><div class="btns"><button class="btn gold" data-act="checkUpdate">🔄 Vérifier la mise à jour</button></div><p class="small mut">Si une nouveauté n’apparaît pas, touchez « Vérifier la mise à jour » : le jeu vide son cache et se recharge (votre partie est gardée).</p>`);
document.addEventListener('DOMContentLoaded',()=>{ setTimeout(()=>{ try{ Object.assign(ACTIONS,{ checkUpdate:()=>checkUpdate(true), whatsNew:()=>openM('whatsnew') });
  checkUpdate(false);
  if(typeof S!=='undefined'&&S&&localStorage.getItem('se-seen-ver')!==GAME_VER){ localStorage.setItem('se-seen-ver',GAME_VER); setTimeout(()=>{ const g=document.getElementById('globe'); if(!UI.modal&&!(g&&!g.hidden)) openM('whatsnew'); },2500); } }catch(e){} },2500); });
